module black_vienna_solver(\n    input wire [2:0] n,\n    input wire [6:0] inv0,\n    input wire [6:0] inv1,\n    input wire [6:0] inv2,\n    input wire [6:0] inv3,\n    input wire [6:0] inv4,\n    output reg [2:0] count\n);\n\n    // Precomputed masks for 4 suspects (A=0, B=1, C=2, D=3)\n    reg [3:0] p1_mask [0:7];\n    reg [3:0] p2_mask [0:7];\n\n    integer init_i;\n    initial begin\n        // Initialize assignments using for-loop\n        for (init_i = 0; init_i < 8; init_i = init_i + 1) begin\n            case (init_i)\n                0: begin p1_mask[0] = 4'b0001; p2_mask[0] = 4'h0; end\n                1: begin p1_mask[1] = 4'h0;    p2_mask[1] = 4'b0001; end\n                2: begin p1_mask[2] = 4'b0010; p2_mask[2] = 4'h0; end\n                3: begin p1_mask[3] = 4'h0;    p2_mask[3] = 4'b0010; end\n                4: begin p1_mask[4] = 4'b0100; p2_mask[4] = 4'h0; end\n                5: begin p1_mask[5] = 4'h0;    p2_mask[5] = 4'b0100; end\n                6: begin p1_mask[6] = 4'b1000; p2_mask[6] = 4'h0; end\n                7: begin p1_mask[7] = 4'h0;    p2_mask[7] = 4'b1000; end\n            endcase\n        end\n    end\n\n    // Decode investigations for up to 5 invs\n    reg [1:0] letter1 [0:4];\n    reg [1:0] letter2 [0:4];\n    reg player [0:4];\n    reg [1:0] reply [0:4];\n\n    always @(*) begin\n        // inv0\n        letter1[0] = inv0[6:5];\n        letter2[0] = inv0[4:3];\n        player[0]  = inv0[2];\n        reply[0]   = inv0[1:0];\n\n        // inv1\n        letter1[1] = inv1[6:5];\n        letter2[1] = inv1[4:3];\n        player[1]  = inv1[2];\n        reply[1]   = inv1[1:0];\n\n        // inv2\n        letter1[2] = inv2[6:5];\n        letter2[2] = inv2[4:3];\n        player[2]  = inv2[2];\n        reply[2]   = inv2[1:0];\n\n        // inv3\n        letter1[3] = inv3[6:5];\n        letter2[3] = inv3[4:3];\n        player[3]  = inv3[2];\n        reply[3]   = inv3[1:0];\n\n        // inv4\n        letter1[4] = inv4[6:5];\n        letter2[4] = inv4[4:3];\n        player[4]  = inv4[2];\n        reply[4]   = inv4[1:0];\n    end\n\n    // For each assignment, compute valid flag\n    reg valid [0:7];\n\n    integer a, i;\n    reg [3:0] current_mask;\n    reg [1:0] count_val;\n\n    always @(*) begin\n        for (a = 0; a < 8; a = a + 1) begin\n            valid[a] = 1'b1;\n            \n            // Check all investigations up to n\n            for (i = 0; i < 5; i = i + 1) begin\n                if (i < n) begin\n                    current_mask = player[i] ? p2_mask[a] : p1_mask[a];\n\n                    // Count matching letters\n                    count_val = 2'd0;\n                    if (current_mask[letter1[i]] == 1'b1)\n                        count_val = count_val + 2'd1;\n                    if (current_mask[letter2[i]] == 1'b1)\n                        count_val = count_val + 2'd1;\n\n                    // Check reply matches count\n                    if (count_val != reply[i]) begin\n                        valid[a] = 1'b0;\n                    end\n                end\n            end\n        end\n    end\n\n    // Count the number of valid assignments\n    always @(*) begin\n        count = 3'd0;\n        for (a = 0; a < 8; a = a + 1) begin\n            if (valid[a]) begin\n                count = count + 3'd1;\n            end\n        end\n    end\n\nendmodule\n